create database retail_sales;

use retail_sales;

select * from retail_sales;

select count(*) as total_records from retail_sales;

-- Q1. Find all unique product categories
select distinct category from retail_sales;

-- Q2. Calculate the total revenue generated by the store.
SELECT
    ROUND(SUM(quantity * price), 2) AS total_revenue
FROM retail_sales;

-- Q3.Display all products in the Electronics category.
SELECT *
FROM retail_sales
WHERE category = 'Electronics';

-- Q4.Find sales where quantity is greater than 3.
SELECT *
FROM retail_sales
WHERE quantity > 3;

-- Q5. Display sales in descending order of price
SELECT *
FROM retail_sales
ORDER BY price DESC;

-- Q6.Find sales between January 1 and March 31, 2025.
SELECT *
FROM retail_sales
WHERE sale_date BETWEEN '2025-01-01' AND '2025-03-31';

-- Q7. Calculate total quantity sold.
SELECT SUM(quantity) AS total_quantity_sold
FROM retail_sales;

-- Q8. Calculate total sales revenue.
 SELECT
    SUM(quantity * price) AS total_revenue
FROM retail_sales;

-- Q9. Find the highest and lowest product prices.
SELECT
    MAX(price) AS highest_price,
    MIN(price) AS lowest_price
FROM retail_sales;

-- Q10. Calculate total revenue by category.
SELECT
    category,
    SUM(quantity * price) AS total_revenue
FROM retail_sales
GROUP BY category
ORDER BY total_revenue DESC;

-- Q11. Find total quantity sold for each product.
SELECT
    product_name,
    SUM(quantity) AS total_quantity
FROM retail_sales
GROUP BY product_name
ORDER BY total_quantity DESC;

-- Q12. Find the top 5 products by revenue.
SELECT
    product_name,
    SUM(quantity * price) AS total_revenue
FROM retail_sales
GROUP BY product_name
ORDER BY total_revenue DESC
LIMIT 5;

-- Q13. Count the number of sales records in each category.
SELECT
    category,
    COUNT(*) AS number_of_sales
FROM retail_sales
GROUP BY category
ORDER BY number_of_sales DESC;

-- Q14. Find products with total revenue greater than ₹50,000.
SELECT
    product_name,
    SUM(quantity * price) AS total_revenue
FROM retail_sales
GROUP BY product_name
HAVING SUM(quantity * price) > 50000
ORDER BY total_revenue DESC;

-- Q15. Find the minimum and maximum product prices.
SELECT MIN(price) AS lowest_price,
       MAX(price) AS highest_price
FROM retail_sales;

-- Q16. Display all sales made in November 2025.
SELECT *
FROM retail_sales
WHERE sale_date >= '2025-11-01'
  AND sale_date < '2025-12-01';
  
-- Q17. Find products whose price is greater than the average product price.
SELECT product_name, price
FROM retail_sales
WHERE price > (
    SELECT AVG(price)
    FROM retail_sales);
    
-- Q18.Find the number of products in each category 
   SELECT category,
       COUNT(DISTINCT product_name) AS total_products
FROM retail_sales
GROUP BY category;

-- Q19. Find products whose price is between 500 and 2000
SELECT product_name, price
FROM retail_sales
WHERE price BETWEEN 500 AND 2000;

-- Q20. Find the total quantity sold for each product
SELECT product_name,
       SUM(quantity * price) AS total_revenue
FROM retail_sales
GROUP BY product_name
ORDER BY total_revenue DESC;

--  Q21.Find the number of sales in each month.
SELECT
    MONTH(sale_date) AS month_number,
    COUNT(*) AS total_sales
FROM retail_sales
GROUP BY MONTH(sale_date)
ORDER BY month_number;

-- Q22. Find the category with the lowest average price.
SELECT
    category,
    AVG(price) AS avg_price
FROM retail_sales
GROUP BY category
ORDER BY avg_price ASC
LIMIT 1;

-- Q23. Find the earliest and latest sale dates and the number of days between them.
SELECT
    MIN(sale_date) AS first_sale_date,
    MAX(sale_date) AS last_sale_date,
    DATEDIFF(MAX(sale_date), MIN(sale_date)) AS date_range_days
FROM retail_sales;

-- Q24. Calculate the average number of units per transaction for each category,
-- and label the performance.
SELECT
    category,
    AVG(quantity) AS average_quantity,
    CASE
        WHEN AVG(quantity) >= 4 THEN 'High Volume'
        ELSE 'Low Volume'
    END AS volume_segment
FROM retail_sales
GROUP BY category;

-- Q25.Find the category with the most transactions.
SELECT
    category,
    COUNT(*) AS total_transactions
FROM retail_sales
GROUP BY category
ORDER BY total_transactions DESC
LIMIT 1;
 
-- Q26.  Count sales recorded in each year.
SELECT
    YEAR(sale_date) AS sales_year,
    COUNT(*) AS total_sales
FROM retail_sales
GROUP BY YEAR(sale_date);

SELECT sale_id, COUNT(*) AS total
FROM retail_sales
GROUP BY sale_id
HAVING COUNT(*) > 1;


--
SELECT *
FROM retail_sales
WHERE sale_id IS NULL
   OR sale_date IS NULL
   OR product_name IS NULL
   OR category IS NULL
   OR quantity IS NULL
   OR price IS NULL;
   
   --
   SELECT COUNT(*) AS total_records
FROM retail_sales;

--
SELECT
    COUNT(*) AS total_records,
    COUNT(DISTINCT product_name) AS unique_products,
    COUNT(DISTINCT category) AS total_categories,
    MIN(sale_date) AS first_sale_date,
    MAX(sale_date) AS last_sale_date
FROM retail_sales;